// Thin trigger: compute today's date (UK). No KPI logic here.
const now = new Date();
const uk = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
return [{ json: { date: uk } }];

// Format the NOVA-assembled report into email HTML. NO KPI logic, NO SQL,
// NO API calls — everything (metrics, RAG, EOD snapshot, AI digests) is already
// in the payload from /api/kpi/daily-report.
const d = $json.data || $json;
const rag = (s) => ({ green: '#10b981', amber: '#eab308', red: '#ef4444' }[s] || '#94a3b8');
let html = `<h2>NOVA KPI Daily — ${d.reportDate}</h2>`;
if (d.digests && d.digests.slt) {
  html += `<h3>SLT Summary</h3><p style="white-space:pre-wrap">${d.digests.slt.summary}</p>`;
}
const dbk = {};
for (const sp of (d.digests && d.digests.spaces) || []) dbk[sp.spaceKey] = sp.summary;
for (const s of d.spaces || []) {
  html += `<h3>${s.displayName} (${s.spaceKey})</h3>`;
  html += `<p>Queue ${s.eodSnapshot.totalTickets} open · ${s.eodSnapshot.overSla} over SLA · `;
  html += `<span style="color:#10b981">${s.ragSummary.green}🟢</span> `;
  html += `<span style="color:#eab308">${s.ragSummary.amber}🟡</span> `;
  html += `<span style="color:#ef4444">${s.ragSummary.red}🔴</span></p>`;
  if (dbk[s.spaceKey]) html += `<p style="white-space:pre-wrap;color:#444">${dbk[s.spaceKey]}</p>`;
  html += '<table cellpadding="4" style="border-collapse:collapse;font-size:13px">';
  for (const m of s.metrics.filter(x => !x.tierName)) {
    html += `<tr><td>${m.displayName}</td><td align="right">${m.value}</td>`;
    html += `<td align="right">${m.target ?? ''}</td>`;
    html += `<td style="color:${rag(m.rag)}">${m.rag ? m.rag.toUpperCase() : ''}</td></tr>`;
  }
  html += '</table>';
}
return [{ json: { subject: `NOVA KPI Daily — ${d.reportDate}`, html } }];
